"""Generate the Contact and not-found pages from structured editorial data.

Jekyll/Liquid snippets are fixed, trusted templates in this module. Values in
JSON are always escaped for both HTML and Liquid. The contact form's availability
is still determined at build time from the existing contact configuration.
"""

from home_render import safe_text

HEADER_CONTACT = "<!-- Generated by .github/scripts/generate_site_content.py; edit _data/contact_page.json. -->"
HEADER_404 = "<!-- Generated by .github/scripts/generate_site_content.py; edit _data/not_found_page.json. -->"

CONTACT_FIELDS = {
    "email_heading", "form_enabled_before", "form_enabled_link",
    "form_enabled_after", "form_disabled_notice", "form_heading",
    "form_intro", "advice_heading", "advice", "social_heading",
    "security_heading", "security_before", "security_between",
    "security_after",
}
NOT_FOUND_FIELDS = {"title", "description", "search_label", "link_labels"}
LINK_KEYS = {"home", "projects", "github", "contact"}


def exact_keys(value, keys, context):
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError(f"{context}: expected exactly {', '.join(sorted(keys))}")


def text(data, key, context):
    return safe_text(data[key], f"{context}.{key}")


def render_contact(data):
    exact_keys(data, CONTACT_FIELDS, "contact page")
    advice = data["advice"]
    if not isinstance(advice, list) or not advice or len(advice) > 15:
        raise ValueError("contact page advice: expected 1-15 entries")
    rows = []
    labels = set()
    for index, entry in enumerate(advice):
        exact_keys(entry, {"label", "description"}, f"advice[{index}]")
        label = text(entry, "label", f"advice[{index}]")
        description = text(entry, "description", f"advice[{index}]")
        if label.casefold() in labels:
            raise ValueError(f"Duplicate advice label: {label}")
        labels.add(label.casefold())
        rows.append((label, description))

    lines = [
        HEADER_CONTACT,
        '{%- assign security_policy_url = site.repository_url | append: "/security/policy" -%}',
        '{%- assign form_key = site.data.contact.form.access_key | strip -%}',
        '<section class="page-section">',
        f'  <h2>{text(data, "email_heading", "contact")}</h2>',
        '  <div class="contact-grid">',
        '    {% include contact-card.html group="business" purposes=true copy=true %}',
        '    {% include contact-card.html group="support" purposes=true copy=true %}',
        '  </div>',
        '  {%- if form_key != "" %}',
        '  <p class="note">{% include icon.html name="mail" %}<span>'
        + text(data, "form_enabled_before", "contact") + ' <a href="#send-a-message">'
        + text(data, "form_enabled_link", "contact") + '</a> '
        + text(data, "form_enabled_after", "contact") + '</span></p>',
        '  {%- else %}',
        '  <p class="note">{% include icon.html name="mail" %}<span>'
        + text(data, "form_disabled_notice", "contact") + '</span></p>',
        '  {%- endif %}',
        '</section>',
        '{%- if form_key != "" %}',
        '',
        '<section class="page-section">',
        f'  <h2 id="send-a-message">{text(data, "form_heading", "contact")}</h2>',
        f'  <p>{text(data, "form_intro", "contact")}</p>',
        '  {% include contact-form.html %}',
        '</section>',
        '{%- endif %}',
        '',
        '<section class="page-section">',
        f'  <h2>{text(data, "advice_heading", "contact")}</h2>',
        '  <ul class="bullet-list">',
    ]
    for label, description in rows:
        lines.append(f'    <li><strong>{label}:</strong> {description}</li>')
    lines.extend([
        '  </ul>',
        '</section>',
        '',
        '<section class="page-section">',
        f'  <h2>{text(data, "social_heading", "contact")}</h2>',
        '  {%- for group_entry in site.data.social.groups %}',
        '    {%- assign group_key = group_entry[0] %}',
        '    {%- assign group = group_entry[1] %}',
        '  <div class="link-group">',
        '    <h3 class="link-group__title">{{ group.title }}</h3>',
        '    {% include profile-list.html group=group_key variant="card" class="link-grid" %}',
        '  </div>',
        '  {%- endfor %}',
        '</section>',
        '',
        '<section class="page-section">',
        f'  <h2>{text(data, "security_heading", "contact")}</h2>',
        '  <p>' + text(data, "security_before", "contact")
        + ' {% include email-link.html key="support" %} '
        + text(data, "security_between", "contact")
        + ' {% include link.html url=security_policy_url label="security policy" %} '
        + text(data, "security_after", "contact") + '</p>',
        '</section>',
        '',
        '<p class="visually-hidden" role="status" data-copy-status></p>',
    ])
    return "\n".join(lines) + "\n"


def render_not_found(data):
    exact_keys(data, NOT_FOUND_FIELDS, "not-found page")
    labels = data["link_labels"]
    exact_keys(labels, LINK_KEYS, "not-found link labels")

    def label(key):
        return text(labels, key, "not-found.link_labels")

    lines = [
        HEADER_404,
        '<section class="error-page">',
        '  <div class="container">',
        '    <p class="error-page__code" aria-hidden="true">404</p>',
        f'    <h1 class="error-page__title">{text(data, "title", "not-found")}</h1>',
        f'    <p class="error-page__text">{text(data, "description", "not-found")}</p>',
        '    <div class="button-row">',
        '      <button class="button button--primary" type="button" '
        '{% include search-attributes.html %} hidden>'
        '{% include icon.html name="search" %}'
        + text(data, "search_label", "not-found") + '</button>',
        '      {% include link.html url="/" label="' + label("home")
        + '" class="button button--secondary" %}',
        '      {% include link.html url=site.projects_url label="' + label("projects")
        + '" class="button button--secondary" hint=true %}',
        '      {% include link.html url=site.data.social.profiles.github.url label="'
        + label("github") + '" icon="github" class="button button--secondary" %}',
        '      {% include link.html url="/contact/" label="' + label("contact")
        + '" class="button button--ghost" %}',
        '    </div>',
        '  </div>',
        '</section>',
    ]
    return "\n".join(lines) + "\n"
